describe('Long-running task persistence across page refreshes', () => {
  const taskStorageKey = 'longRunningTask';
  const taskStatusKey = 'taskStatus';

  beforeEach(() => {
    cy.clearLocalStorage();
    cy.visit('http://localhost:3000');
  });

  it('should persist task progress across page refresh', () => {
    // Start a long-running task
    cy.get('[data-testid="start-task-btn"]').click();

    // Verify task has started and is stored in localStorage
    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData).to.exist;
      expect(taskData.status).to.equal('in_progress');
      expect(taskData.startTime).to.be.a('number');
    });

    // Wait for some progress to be made
    cy.wait(2000);

    // Capture current progress before refresh
    cy.window().then((win) => {
      const taskDataBefore = JSON.parse(win.localStorage.getItem(taskStorageKey));
      const progressBefore = taskDataBefore.progress;

      // Refresh the page
      cy.reload();

      // Verify task data persists after refresh
      cy.window().then((winAfter) => {
        const taskDataAfter = JSON.parse(winAfter.localStorage.getItem(taskStorageKey));
        expect(taskDataAfter).to.exist;
        expect(taskDataAfter.status).to.equal('in_progress');
        expect(taskDataAfter.startTime).to.equal(taskDataBefore.startTime);
        expect(taskDataAfter.progress).to.be.at.least(progressBefore);
      });
    });

    // Verify UI reflects persisted task state
    cy.get('[data-testid="task-progress"]').should('be.visible');
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
  });

  it('should handle task completion and persist final state across refresh', () => {
    // Start task
    cy.get('[data-testid="start-task-btn"]').click();

    // Wait for task to complete (adjust timeout based on actual task duration)
    cy.get('[data-testid="task-status"]', { timeout: 15000 }).should('contain', 'Completed');

    // Verify completion is stored
    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData.status).to.equal('completed');
      expect(taskData.progress).to.equal(100);
      expect(taskData.completionTime).to.be.a('number');
    });

    // Refresh page
    cy.reload();

    // Verify completed state persists
    cy.get('[data-testid="task-status"]').should('contain', 'Completed');
    cy.get('[data-testid="task-progress"]').should('contain', '100%');

    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData.status).to.equal('completed');
      expect(taskData.progress).to.equal(100);
    });
  });

  it('should handle multiple page refreshes during task execution', () => {
    cy.get('[data-testid="start-task-btn"]').click();

    // First refresh
    cy.wait(1000);
    cy.reload();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');

    // Second refresh
    cy.wait(1000);
    cy.reload();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');

    // Third refresh
    cy.wait(1000);
    cy.reload();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');

    // Verify data integrity after multiple refreshes
    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData).to.exist;
      expect(taskData.status).to.be.oneOf(['in_progress', 'completed']);
    });
  });

  it('should handle task cancellation and persist cancelled state', () => {
    cy.get('[data-testid="start-task-btn"]').click();

    // Wait for task to start
    cy.wait(1000);

    // Cancel the task
    cy.get('[data-testid="cancel-task-btn"]').click();

    // Verify cancellation is stored
    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData.status).to.equal('cancelled');
    });

    // Refresh page
    cy.reload();

    // Verify cancelled state persists
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="start-task-btn"]').should('be.enabled');

    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData.status).to.equal('cancelled');
    });
  });

  it('should handle edge case of corrupted localStorage data gracefully', () => {
    // Simulate corrupted data
    cy.window().then((win) => {
      win.localStorage.setItem(taskStorageKey, 'invalid json {]');
    });

    cy.reload();

    // Should not crash and should allow starting a new task
    cy.get('[data-testid="start-task-btn"]').should('be.enabled').click();

    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      expect(taskData).to.exist;
      expect(taskData.status).to.equal('in_progress');
    });
  });

  it('should handle rapid successive page refreshes without data loss', () => {
    cy.get('[data-testid="start-task-btn"]').click();

    cy.window().then((win) => {
      const initialTaskData = JSON.parse(win.localStorage.getItem(taskStorageKey));
      const initialStartTime = initialTaskData.startTime;

      // Perform rapid refreshes
      for (let i = 0; i < 3; i++) {
        cy.reload();
        cy.window().then((winAfter) => {
          const taskData = JSON.parse(winAfter.localStorage.getItem(taskStorageKey));
          expect(taskData.startTime).to.equal(initialStartTime);
          expect(taskData.status).to.not.be.empty;
        });
      }
    });
  });
});
